namespace HaelpMi.Core.Models;

/// <summary>
/// Fixed at build time by the Install-Creator, shipped as a small JSON file inside the
/// installer payload (see Install-Creator/DeploymentWriter) and copied to
/// <c>{app}\deployment.json</c> next to the executables. Read once at startup - never
/// user-editable, never regenerated by the running app itself.
///
/// <see cref="CustomerGroupId"/> is what lets two independent HälpMi installations
/// coexist on the same physical network without ever seeing each other (Pflichtenheft
/// Teil 2, Abschnitt 6): every network packet carries it, and a receiver silently drops
/// anything with a different value.
/// </summary>
public sealed class DeploymentInfo
{
    public required Guid CustomerGroupId { get; set; }

    public required Role Role { get; set; }

    /// <summary>
    /// True for installers built with the Install-Creator's "Test-Installer" checkbox
    /// (installer password optional, no customer name required). Never true for a real
    /// deployment - purely a build-time flag carried through so the running app can, if
    /// useful later, show a "Test-Build" marker; nothing in Phase-2 scope currently
    /// branches on it at runtime beyond that.
    /// </summary>
    public bool IsTestInstaller { get; set; }

    // Multi-VLAN-Bootstrap-Seed (Nutzerwunsch 13.08.2026) hatte hier von 13.-15.08.2026 einen
    // Startwert namens BridgeSeedAddress - entfernt (Nutzerwunsch 15.08.2026): mit der
    // admin-editierbaren, hot-reload-verteilten Liste in SharedConfig.BridgeSeedAddresses
    // war der Install-Creator-Startwert überflüssig geworden (der Admin pflegt die
    // Bridge-Adressen jetzt vollständig im Dashboard, kein Installer-Neubau nötig). Alte
    // deployment.json-Dateien mit dem jetzt unbekannten Feld werden beim Deserialisieren
    // einfach ignoriert (System.Text.Json), kein Migrationsschritt nötig.
}
